use anyhow::{Result,ensure};use glam::Mat4;
use crate::{Prepared,gpu::Gpu,scene::Scene,hud::Hud,log::{Log,root}};
pub fn run(log:&Log,prepared:Prepared)->Result<()>{let mut gpu=Gpu::new(log,None,0xb000)?;let mut scene=Scene::new(prepared.source,prepared.assets,&mut gpu)?;ensure!(scene.source.manifest().version==2,"투사체 v2 자료 필요");scene.hud_scale=0.45;scene.elapsed_seconds=12.0;let mut hud=Hud::new(&scene.assets.portraits)?;let(texture,target)=gpu.offscreen(1600,1100)?;let projection=Mat4::perspective_rh(42f32.to_radians(),1600.0/1100.0,0.01,40.0);let mut reports=Vec::new();
 for (name,time,az)in[("first",520.0,0.0),("max",39637.0,0.0),("half",39637.5,0.0),("left",39637.0,-60.0),("right",39637.0,60.0),("middle",24600.0,0.0),("fallback",18947.0,0.0)]{scene.seek(time);let(head,q,view)=crate::capture::camera(az,42.0,3.7);for _ in 0..12{scene.update(&mut gpu,head,q,0.1)?;}gpu.update_hud(hud.render(&scene.hud_content()))?;gpu.mask(|_|true);gpu.render(&target,projection*view,scene.world(),true);gpu.save_png(&texture,&root().join(format!("_tmp/shots/native_projectile_{name}.png")))?;let(_,_,with)=gpu.pixels(&texture)?;gpu.mask(|n|n!="projectiles");gpu.render(&target,projection*view,scene.world(),true);let(_,_,without)=gpu.pixels(&texture)?;gpu.save_png(&texture,&root().join(format!("_tmp/shots/native_projectile_{name}_without.png")))?;gpu.mask(|_|true);let changed=with.chunks_exact(4).zip(without.chunks_exact(4)).filter(|(a,b)|a[..3].iter().zip(&b[..3]).map(|(a,b)|a.abs_diff(*b)as u32).sum::<u32>()>10).count();reports.push(serde_json::json!({"name":name,"time":time,"az":az,"sourceRows":scene.source.pair(time).a.projectiles,"flights":scene.projectile_snapshot(),"renderedCount":scene.projectile_count,"changedPixels":changed,"drawCalls":gpu.calls+1,"snapshot":scene.snapshot()}));}
 ensure!(reports.iter().any(|r|r["changedPixels"].as_u64().unwrap()>0),"투사체 화면 기여 없음");let report=serde_json::json!({"검증":"통과","최대동시":scene.source.max_projectiles(),"reports":reports,"그림선택":"공식API에 종류 없음 · 시전자별 투사체 태그/자산으로 추정 · 없으면 팀빛","heightM":0.035,"실기기":"이번 투사체 수정본 미검증"});std::fs::write(root().join("_tmp/logs/native_projectile_capture.json"),serde_json::to_vec_pretty(&report)?)?;gpu.check()?;log.line("투사체 위치/그림 추정/팀빛/깊이 캡처 완료");Ok(())}
